#include "support/process.hpp"
using namespace test;
int main(int argc,char** argv){try{check(argc==2||argc==3,"fixture and optional fork required");Temp root;
 auto args=[&](const std::string& phase){std::vector<std::string> values{argv[1],phase,root.path.string()};if(argc==3)values.push_back(argv[2]);return values;};
 auto interrupted=[&](const std::string& phase){Process child(args(phase));auto value=Json::parse(child.line([](const std::string& s){return !s.empty()&&s[0]=='{';},15));check(value["phase"]==phase&&child.running(),"phase acknowledgement missing");child.signal(SIGKILL);check(child.wait(10).code==-SIGKILL,"fixture was not killed abruptly");return value;};
 auto reserved=interrupted("reserve");check(reserved["height"]=="0x0"&&reserved["votingHeight"]==1,"reserve boundary");auto committed=interrupted("commit");check(committed["height"]=="0x1"&&committed["votingHeight"]==1,"commit boundary");check(committed["signature"]==reserved["signature"]&&committed["recoveredSignature"]==reserved["signature"]&&committed["blockHash"]==reserved["blockHash"],"recovered signature or block differs");
 check(committed["conflictingVoteRejected"]==true,"restart did not prove conflicting vote rejection");
 auto recovered=interrupted("recover");check(recovered["height"]=="0x1"&&recovered["votingHeight"]==2,"recovery boundary");auto result=success(run(args("verify")));check(result["height"]=="0x2"&&result["votingHeight"]==3&&result["audit"]["verified"].get<bool>()&&result["audit"]["certifiedBlocks"]=="0x2","post-crash state or certificate mismatch");std::cout<<Json{{"fork",argc==3?argv[2]:"NanoExperimental"},{"sigkillBoundaries",3},{"reserved",reserved},{"committed",committed},{"recovered",recovered},{"verified",result}}.dump()<<std::endl;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
